var t=[{title:`Het grote geheel`,text:`Training gebruikt energie, en voeding levert wat je nodig hebt om te trainen, te herstellen en weefsel op te bouwen. Een gevarieerd dieet bevat meestal eiwitrijke voeding, koolhydraatrijke voeding, fruit, groenten en bronnen van vet. Zeer restrictief eten kan je prestaties en herstel tegenhouden, ook als je trainingen goed zijn opgezet.`},{title:`Eiwit en spieren`,text:`Eiwit levert aminozuren die je lichaam gebruikt om weefsel te onderhouden en spieren aan te passen. Onderzoek bij trainende volwassenen noemt vaak ongeveer 1,4–2,0 gram eiwit per kilogram lichaamsgewicht per dag als een op bewijs gebaseerd bereik. Behoeften verschillen met leeftijd, training en persoonlijke omstandigheden, en je hoeft dit getal niet uit te rekenen.`},{title:`Koolhydraten en vetten`,text:`Koolhydraten voeden herhaalde zware inspanningen en duurtrainingen door het spierglycogeen op peil te houden. Vet uit voeding levert essentiële vetzuren en helpt je bepaalde vitaminen op te nemen. Gedetailleerde sportvoedingsstrategieën worden belangrijker naarmate je trainingsvolume stijgt. Richt je als beginner eerst op regelmatige, evenwichtige maaltijden.`},{title:`Voorbeeld`,text:`Train je drie dagen per week kracht, dan kun je maaltijden opbouwen rond bonen, vis, eieren of een andere eiwitbron, granen of aardappelen voor energie toevoegen en groenten en fruit opnemen. Wat je over de week eet, telt zwaarder dan een bepaalde shake drinken direct na elke set.`},{title:`Wanneer je deskundige hulp zoekt`,text:`Heb je een medische aandoening, zorgen over eten of een gespecialiseerd prestatiedoel, praat dan met een diëtist of een zorgverlener. TrainUp geeft geen individuele caloriedoelen, macrotracking of maaltijdplannen om af te vallen.`}];var i=[{label:`Standpunt van de ISSN: eiwit en training`,url:`https://pmc.ncbi.nlm.nih.gov/articles/PMC5477153/`},{label:`Standpunt van het ACSM uit 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var r={sections:t,sources:i};export{r as default,t as sections,i as sources};